        key = _codec(fn, name, args[0], ())
        value = _codec(fn, name, args[1], ())
        composite = {CodecKind.SEQUENCE, CodecKind.TUPLE, CodecKind.MAPPING}
        if key.kind in composite or value.kind in composite:
